import itertools

# Coefficients C_j = 7^j * (35 - 6j) for j=0 to 6
coefficients = {}
for j in range(7):
    C_j = (7**j) * (35 - 6*j)
    coefficients[j] = C_j

# The equation is: sum(b_j * C_j) = 0
# b_j must be in {0, 1, ..., 6}
digits = range(7)
solution_count = 0

# Iterate over all 7^7 possible sequences (b0, b1, ..., b6)
for sequence in itertools.product(digits, repeat=7):
    current_sum = 0
    for j in range(7):
        b_j = sequence[j]
        current_sum += b_j * coefficients[j]

    if current_sum == 0:
        solution_count += 1

print(f"The number of solutions is: {solution_count}")
